/// One table: each icon's file in assets/icons (named as in the generator's
/// output) and its embedded artwork. Add Loop uses the Loop Cut artwork;
/// Script Action is shared by the script command rows.
macro_rules! icon_files {
    (
        $($(#[$m:meta])* $icon:ident => $file:literal,)*
        ; rendered only: $($ricon:ident => $rslug:literal,)*
    ) => {
        impl Icon {
            /// The icons drawn by the old generator, with an SVG.
            #[cfg(test)]
            pub const ALL: &'static [Icon] = &[$($(#[$m])* Icon::$icon),*];
            /// New icons with rendered artwork only (icon studio), and their
            /// studio slugs. `rendered_icons::RENDERED` must list them.
            pub const RENDERED_ONLY: &'static [(Icon, &'static str)] =
                &[$((Icon::$ricon, $rslug)),*];
            #[cfg(test)]
            pub fn file(self) -> &'static str {
                match self {
                    $($(#[$m])* Icon::$icon => $file,)*
                    $(Icon::$ricon => "",)*
                }
            }
            /// The generator's SVG, if the icon has one.
            fn svg(self) -> Option<&'static str> {
                match self {
                    $($(#[$m])* Icon::$icon => Some(include_str!(concat!("../assets/icons/", $file))),)*
                    $(Icon::$ricon => None,)*
                }
            }
            /// The icon's slug: the generator's file name without `.svg`,
            /// or the studio slug of a rendered-only icon.
            pub fn slug(self) -> &'static str {
                const FILES: &[(Icon, &str)] = &[$($(#[$m])* (Icon::$icon, $file)),*];
                FILES
                    .iter()
                    .find(|(icon, _)| *icon == self)
                    .and_then(|(_, file)| file.strip_suffix(".svg"))
                    .or_else(|| {
                        Self::RENDERED_ONLY
                            .iter()
                            .find(|(icon, _)| *icon == self)
                            .map(|(_, slug)| *slug)
                    })
                    .unwrap_or_default()
            }
            /// The icon whose slug is `slug`, as data such as the tool
            /// preset table and form JSON name them.
            pub fn from_slug(slug: &str) -> Option<Icon> {
                const FILES: &[(Icon, &str)] = &[$($(#[$m])* (Icon::$icon, $file)),*];
                FILES
                    .iter()
                    .find(|(_, file)| file.strip_suffix(".svg") == Some(slug))
                    .map(|(icon, _)| *icon)
                    .or_else(|| {
                        Self::RENDERED_ONLY
                            .iter()
                            .find(|(_, s)| *s == slug)
                            .map(|(icon, _)| *icon)
                    })
            }
        }
    };
}
