fn rasterize(icon: Icon, pixels: u32) -> Result<ColorImage, String> {
    let svg = icon
        .svg()
        .ok_or_else(|| format!("Icon {icon:?} has only rendered artwork"))?;
    let tree = resvg::usvg::Tree::from_str(svg, &Default::default())
        .map_err(|e| format!("Dictionary icon {icon:?}: {e}"))?;
    let mut pixmap = resvg::tiny_skia::Pixmap::new(pixels, pixels)
        .ok_or_else(|| format!("Cannot allocate dictionary icon {icon:?}"))?;
    resvg::render(
        &tree,
        resvg::tiny_skia::Transform::from_scale(
            pixels as f32 / tree.size().width(),
            pixels as f32 / tree.size().height(),
        ),
        &mut pixmap.as_mut(),
    );
    Ok(ColorImage::from_rgba_premultiplied(
        [pixels as usize; 2],
        pixmap.data(),
    ))
}

/// Textures by icon, pixel size and, for rendered icons, outline set.
#[derive(Clone, Default)]
struct Cache(BTreeMap<(Icon, u32, Option<crate::rendered_icons::IconSet>), TextureHandle>);

/// Rasterize at drawable resolution, with a bounded context-owned GPU cache.
/// Original colors/alpha/gradients are preserved; active chrome never tints art.
pub fn paint(ui: &Ui, rect: Rect, icon: Icon) {
    paint_rotated(ui, rect, icon, 0.);
}
/// A disabled control's icon: the same art, faded like its greyed label.
pub fn paint_faded(ui: &Ui, rect: Rect, icon: Icon) {
    paint_tinted(ui, rect, icon, 0., Color32::from_white_alpha(90));
}
fn paint_rotated(ui: &Ui, rect: Rect, icon: Icon, angle: f32) {
    paint_tinted(ui, rect, icon, angle, Color32::WHITE);
}
/// A single-tone icon (drawn light) in `tint`: list glyphs (N16).
pub fn paint_in(ui: &Ui, rect: Rect, icon: Icon, tint: Color32) {
    paint_tinted(ui, rect, icon, 0., tint);
}
/// The list disclosure triangle in `tint` (N16).
pub fn disclosure_in(ui: &Ui, rect: Rect, openness: f32, tint: Color32) {
    paint_tinted(
        ui,
        rect,
        Icon::DisclosureMono,
        (openness - 1.) * std::f32::consts::FRAC_PI_2,
        tint,
    );
}
fn paint_tinted(ui: &Ui, rect: Rect, icon: Icon, angle: f32, tint: Color32) {
    if !ui.is_rect_visible(rect) {
        return;
    }
    let ppp = ui.ctx().pixels_per_point();
    let rect = snap_to_pixels(rect, ppp);
    let pixels = (rect.width().max(rect.height()) * ppp)
        .round()
        .clamp(1., 256.) as u32;
    let Some(texture) = texture(ui, icon, pixels) else {
        return;
    };
    Image::new(&texture)
        .rotate(angle, vec2(0.5, 0.5))
        .tint(tint)
        .paint_at(ui, rect);
}

/// `rect` moved and sized onto whole device pixels, about its centre, so an
/// icon's picture lands pixel for pixel instead of being resampled across
/// pixel edges: at Windows' 125% and 150% scales and other fractional
/// `pixels_per_point`, a point position is often between pixels.
pub fn snap_to_pixels(rect: Rect, pixels_per_point: f32) -> Rect {
    let ppp = pixels_per_point.max(0.25);
    let size = vec2(
        (rect.width() * ppp).round().max(1.) / ppp,
        (rect.height() * ppp).round().max(1.) / ppp,
    );
    let min = rect.center() - size / 2.;
    Rect::from_min_size(
        pos2((min.x * ppp).round() / ppp, (min.y * ppp).round() / ppp),
        size,
    )
}

/// Shared texture source for painted glyphs and native egui icon+label controls.
fn texture(ui: &Ui, icon: Icon, pixels: u32) -> Option<TextureHandle> {
    // Rendered icons (rendered_icons.rs) come from the chosen outline set;
    // the rest are the generator's SVGs.
    let set = crate::rendered_icons::slug(icon).map(|_| crate::rendered_icons::current_set());
    let key = (icon, pixels, set);
    let id = Id::new("admitted dictionary textures");
    let cached = ui.ctx().data_mut(|data| {
        data.get_temp_mut_or_default::<Cache>(id)
            .0
            .get(&key)
            .cloned()
    });
    let texture = match cached {
        Some(texture) => texture,
        None => {
            let image = match set
                .and_then(|set| crate::rendered_icons::rasterize(icon, set, pixels))
                .unwrap_or_else(|| rasterize(icon, pixels))
            {
                Ok(image) => image,
                Err(error) => {
                    crate::log_ring::log_line!("{error}");
                    return None;
                }
            };
            let texture = ui.ctx().load_texture(
                format!("dictionary/{icon:?}/{pixels}/{set:?}"),
                image,
                TextureOptions::LINEAR,
            );
            ui.ctx().data_mut(|data| {
                let cache = &mut data.get_temp_mut_or_default::<Cache>(id).0;
                if cache.len() >= 64 {
                    cache.clear();
                }
                cache.insert(key, texture.clone());
            });
            texture
        }
    };
    Some(texture)
}

/// Keep the toolkit's button/menu/focus/disabled behavior and original art colors.
/// 16 logical pixels fits the existing compact 22-pixel context toolbar row.
pub fn button(ui: &Ui, icon: Icon, label: &str) -> Button<'static> {
    let pixels = (16. * ui.ctx().pixels_per_point()).ceil().clamp(1., 256.) as u32;
    let image = texture(ui, icon, pixels).map(|t| Image::new((t.id(), vec2(16., 16.))));
    Button::opt_image_and_text(image, Some(label.to_owned().into()))
        .image_tint_follows_text_color(false)
}

/// [`button`] with a rich label (the Render button's dimmer shortcut).
pub fn button_with(ui: &Ui, icon: Icon, label: WidgetText) -> Button<'static> {
    let pixels = (16. * ui.ctx().pixels_per_point()).ceil().clamp(1., 256.) as u32;
    let image = texture(ui, icon, pixels).map(|t| Image::new((t.id(), vec2(16., 16.))));
    Button::opt_image_and_text(image, Some(label)).image_tint_follows_text_color(false)
}

/// One admitted tab.collapse drawing; rotation supplies the closed orientation.
pub fn disclosure(ui: &Ui, rect: Rect, openness: f32) {
    paint_rotated(
        ui,
        rect,
        Icon::Disclosure,
        (openness - 1.) * std::f32::consts::FRAC_PI_2,
    );
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn icons_land_on_whole_device_pixels_at_fractional_scales() {
        // A 32-point toolbox icon at a fractional point position, at
        // Windows' 125% and 150% and a 3x dense display.
        for ppp in [1., 1.25, 1.5, 3.] {
            let r = snap_to_pixels(Rect::from_min_size(pos2(10.3, 7.7), vec2(32., 32.)), ppp);
            for v in [r.min.x, r.min.y, r.width(), r.height()] {
                let px = v * ppp;
                assert!((px - px.round()).abs() < 1e-3, "{v} at {ppp}");
            }
            let moved = r.center() - pos2(26.3, 23.7);
            assert!(moved.x.abs().max(moved.y.abs()) <= 0.5 / ppp + 1e-4);
        }
    }
    #[test]
    fn admitted_art_rasterizes_at_control_sizes_and_display_scales() {
        for icon in [
            Icon::Cube,
            Icon::Sphere,
            Icon::Ellipsoid,
            Icon::Torus,
            Icon::Capsule,
            Icon::Arc,
            Icon::Tube,
            Icon::Bridge,
            Icon::Spike,
            Icon::Cylinder,
            Icon::Transform,
            Icon::Vertex,
            Icon::Edge,
            Icon::Polygon,
            Icon::Move,
            Icon::Rotate,
            Icon::Scale,
            Icon::Bevel,
            Icon::Thicken,
            Icon::Extrude,
            Icon::Eye,
            Icon::Disclosure,
            Icon::ActionCenter,
            Icon::Falloff,
            Icon::Symmetry,
            Icon::Snapping,
            Icon::Workplane,
            Icon::Triple,
            Icon::Reduction,
            Icon::ScriptAction,
            Icon::ScaleOffset,
            Icon::ScaleOffsetDetach,
            Icon::FlattenNgons,
            Icon::TagMaterial,
            Icon::TagPart,
            Icon::TagSmoothingGroup,
            Icon::TagSelectionSet,
            Icon::PenSlice,
            Icon::CurveSlice,
            Icon::PrimitiveSlice,
            Icon::AxisSlice,
            Icon::Dicer,
            Icon::Julienne,
            Icon::SolidSketch,
            Icon::TopologyPen,
        ] {
            for logical in [12., 16., 20., 24., 32.] {
                for scale in [1., 1.5, 2.] {
                    let pixels = (logical * scale) as u32;
                    let image = rasterize(icon, pixels).unwrap();
                    assert_eq!(image.size, [pixels as usize; 2]);
                    assert!(image.pixels.iter().any(|p| p.a() > 0), "{icon:?}");
                    assert!(image.pixels.iter().any(|p| p.a() == 0), "{icon:?}");
                }
            }
        }
    }
}

#[cfg(test)]
mod generated_tests {
    use super::*;
    use std::path::Path;

    /// The app's icons are the generator's output, unchanged. If this fails,
    /// regenerate (tools/operandi-icons) and copy generated/svg/*.svg here.
    #[test]
    fn app_icons_match_the_generator() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR"));
        let generated = root.join("../../tools/operandi-icons/generated/svg");
        for &icon in Icon::ALL {
            let made = std::fs::read_to_string(generated.join(icon.file())).unwrap_or_else(|e| {
                panic!("{icon:?}: {} missing from the generator ({e})", icon.file())
            });
            assert_eq!(
                icon.svg().unwrap_or_default(),
                made,
                "{icon:?} differs from the generated {}",
                icon.file()
            );
        }
        for entry in std::fs::read_dir(root.join("assets/icons")).unwrap() {
            let name = entry.unwrap().file_name().into_string().unwrap();
            assert!(
                generated.join(&name).is_file(),
                "assets/icons/{name} isn't generated"
            );
        }
    }

    #[test]
    fn every_icon_rasterizes() {
        for &icon in Icon::ALL {
            let image = rasterize(icon, 32).unwrap_or_else(|e| panic!("{e}"));
            assert!(image.pixels.iter().any(|p| p.a() > 0), "{icon:?} is blank");
        }
    }
}
